BEGIN;
CREATE TABLE ivr_audio_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,description text NOT NULL DEFAULT '',active_version integer,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE ivr_audio_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),asset_id uuid NOT NULL REFERENCES ivr_audio_assets(id) ON DELETE CASCADE,version integer NOT NULL,object_key text NOT NULL UNIQUE,codec text NOT NULL CHECK(codec IN('wav','mp3','ogg','opus','gsm')),size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1024 AND 52428800),sha256 text NOT NULL CHECK(length(sha256)=64),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','approved','rejected','retired')),review_note text,uploaded_by uuid,reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(asset_id,version));
CREATE TABLE tenant_branding(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),product_name text NOT NULL DEFAULT 'Llamar',logo_url text,primary_color text NOT NULL DEFAULT '#2DE2A5',secondary_color text NOT NULL DEFAULT '#101722',email_from_name text NOT NULL DEFAULT 'Llamar',sms_sender_name text NOT NULL DEFAULT 'LLAMAR',support_url text,custom_domain text UNIQUE,domain_status text NOT NULL DEFAULT 'unconfigured' CHECK(domain_status IN('unconfigured','pending','verified','failed')),updated_by uuid,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),feature_key text NOT NULL,enabled boolean NOT NULL DEFAULT true,limit_value bigint,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,feature_key));
CREATE TABLE billing_rates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),provider_key text NOT NULL,country_code text NOT NULL DEFAULT '*',provider_rate_minor_per_min integer NOT NULL CHECK(provider_rate_minor_per_min>=0),client_rate_minor_per_min integer NOT NULL CHECK(client_rate_minor_per_min>=0),connection_fee_minor integer NOT NULL DEFAULT 0 CHECK(connection_fee_minor>=0),bill_failed boolean NOT NULL DEFAULT false,effective_from timestamptz NOT NULL DEFAULT now(),effective_until timestamptz,UNIQUE(tenant_id,provider_key,country_code,effective_from));
CREATE TABLE call_usage_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),call_session_id uuid NOT NULL REFERENCES call_sessions(id),provider_key text NOT NULL,disposition text NOT NULL,duration_seconds integer NOT NULL DEFAULT 0,provider_cost_minor bigint NOT NULL,client_charge_minor bigint NOT NULL,billable boolean NOT NULL,currency char(3) NOT NULL DEFAULT 'INR',reconciliation_state text NOT NULL DEFAULT 'reconciled' CHECK(reconciliation_state IN('pending','reconciled','disputed','reversed')),idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,call_session_id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE billing_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,currency char(3) NOT NULL,total_calls integer NOT NULL,total_charge_minor bigint NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','issued','void')),issued_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,period_start,period_end));
CREATE TABLE operational_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),severity text NOT NULL CHECK(severity IN('info','warning','critical')),source text NOT NULL,title text NOT NULL,detail text NOT NULL,dedupe_key text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','acknowledged','resolved')),acknowledged_by uuid,acknowledged_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,dedupe_key,status));
ALTER TABLE ivr_audio_assets ENABLE ROW LEVEL SECURITY;ALTER TABLE ivr_audio_assets FORCE ROW LEVEL SECURITY;ALTER TABLE ivr_audio_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE ivr_audio_versions FORCE ROW LEVEL SECURITY;ALTER TABLE tenant_branding ENABLE ROW LEVEL SECURITY;ALTER TABLE tenant_branding FORCE ROW LEVEL SECURITY;ALTER TABLE tenant_entitlements ENABLE ROW LEVEL SECURITY;ALTER TABLE tenant_entitlements FORCE ROW LEVEL SECURITY;ALTER TABLE billing_rates ENABLE ROW LEVEL SECURITY;ALTER TABLE billing_rates FORCE ROW LEVEL SECURITY;ALTER TABLE call_usage_ledger ENABLE ROW LEVEL SECURITY;ALTER TABLE call_usage_ledger FORCE ROW LEVEL SECURITY;ALTER TABLE billing_invoices ENABLE ROW LEVEL SECURITY;ALTER TABLE billing_invoices FORCE ROW LEVEL SECURITY;ALTER TABLE operational_alerts ENABLE ROW LEVEL SECURITY;ALTER TABLE operational_alerts FORCE ROW LEVEL SECURITY;
CREATE POLICY ivr_assets_iso ON ivr_audio_assets USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY ivr_versions_iso ON ivr_audio_versions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY branding_iso ON tenant_branding USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY entitlements_iso ON tenant_entitlements USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY billing_rates_iso ON billing_rates USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY usage_iso ON call_usage_ledger USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY invoices_iso ON billing_invoices USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY alerts_iso ON operational_alerts USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE OR REPLACE FUNCTION reject_usage_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'call usage ledger is append-only';END;$$;CREATE TRIGGER usage_no_mutation BEFORE UPDATE OR DELETE ON call_usage_ledger FOR EACH ROW EXECUTE FUNCTION reject_usage_mutation();
COMMIT;
